def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "resource_collection")
    self_pos = observation.get("self_position") or [0, 0]
    opp_pos = observation.get("opponent_position") or self_pos
    sx, sy = self_pos[0], self_pos[1]
    ox, oy = opp_pos[0], opp_pos[1]

    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0
    center = [gw // 2, gh // 2] if gw and gh else [sx, sy]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward([sx, sy], [ox, oy])
        corners = [[0, 0], [0, max(0, gh - 1)], [max(0, gw - 1), 0], [max(0, gw - 1), max(0, gh - 1)]]
        target = corners[0]
        best_score = -10**9
        for c in corners:
            score = manhattan(c, [ox, oy])
            if score > best_score:
                best_score = score
                target = c
        move = step_toward([sx, sy], target)
        if move == [0, 0]:
            move = step_toward([sx, sy], center)
        return move

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_score = 10**9
        for item in targets:
            if item and len(item) >= 2:
                score = manhattan([sx, sy], [item[0], item[1]])
                if score < best_score:
                    best_score = score
                    best = item
        if best is not None:
            return step_toward([sx, sy], [best[0], best[1]])
        return step_toward([sx, sy], center)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_score = 10**9
    for item in resources:
        if item and len(item) >= 2:
            score = manhattan([sx, sy], [item[0], item[1]])
            if score < best_score:
                best_score = score
                best = item
    if best is not None:
        return step_toward([sx, sy], [best[0], best[1]])

    return step_toward([sx, sy], center)

